AppletCode = NULL;	CJavaAutoText_AC theURL(baseURL);	CJavaAutoText_AC theAppletCode(appletCode);		fBaseURL = theURL.release();	fAppletCode = theAppletCode.release();#endif}//----------------------------------------------------------------------------------------// CTempJavaAppletLocator_AC::CTempJavaAppletLocator_AC//----------------------------------------------------------------------------------------CTempJavaAppletLocator_AC::CTempJavaAppletLocator_AC(	const CStr255_AC& baseURL,														const CStr255_AC& appletCode,														short width, short height){	fVersion = kJMVersion;	fWidth = width;	fHeight = height;	fOptionalParameterCount = 0;	fParams = NULL;	fBaseURL = NULL;	fAppletCode = NULL;	CJavaAutoText_AC theURL(baseURL);	CJavaAutoText_AC theAppletCode(appletCode);		fBaseURL = theURL.release();	fAppletCode = theAppletCode.release();}//----------------------------------------------------------------------------------------// CTempJavaAppletLocator_AC::~CTempJavaAppletLocator_AC//----------------------------------------------------------------------------------------CTempJavaAppletLocator_AC::~CTempJavaAppletLocator_AC(){	CJavaAutoText_AC theURL(fBaseURL);	CJavaAutoText_AC theAppletCode(fAppletCode);#if qDebug	fBaseURL = NULL;	fAppletCode = NULL;#endif}		//----------------------------------------------------------------------------------------// CTempJavaAppletLocator_AC::GetURL//----------------------------------------------------------------------------------------CStr255_AC CTempJavaAppletLocator_AC::GetURL() const// GetURL returns the URL as a CStr255_AC.{	return static_cast<CStr255_AC>(CJavaText_AC(fBaseURL));}//----------------------------------------------------------------------------------------// End of CJavaAppletLocator_AC.cpp